import fs from "node:fs";
import path from "node:path";

const repositoryRoot = path.resolve(import.meta.dirname, "../../..");
const shopSnapshot = path.join(repositoryRoot, "data", "generated", "server", "shops.json");
const oldMetadata =
    "Generated by server/scripts/build-shops.ts from DayV osrsreboxed-db shop dumps + npc-spawns.json. Regenerate with yarn build-shops.";
const canonicalMetadata =
    "Generated by tools/data/build-shops.ts from DayV osrsreboxed-db shop dumps + npc-spawns.json. Regenerate with pnpm --filter @august/server build-shops.";

const source = fs.readFileSync(shopSnapshot, "utf8");
if (source.includes(canonicalMetadata)) {
    console.log("Generated shop metadata is already canonical.");
} else if (source.includes(oldMetadata)) {
    fs.writeFileSync(shopSnapshot, source.replace(oldMetadata, canonicalMetadata));
    console.log("Updated generated shop metadata without regenerating game data.");
} else {
    throw new Error("Expected generated shop metadata was not found");
}
